from __future__ import annotations
from itertools import combinations
from typing import Iterator, Sequence

Matrix = Sequence[Sequence[float]]
Subset = frozenset[int]

def subsets(n: int) -> Iterator[Subset]:
    for size in range(1, n):
        for chosen in combinations(range(n), size):
            yield frozenset(chosen)

def cut_weight(w: Matrix, a: Subset) -> float:
    return sum(w[i][j] for i in a for j in range(len(w)) if j not in a)

def minimum_information_partition(w: Matrix) -> tuple[float, Subset]:
    n = len(w)
    if n < 2 or any(len(row) != n for row in w):
        raise ValueError("Expected a square matrix of order at least two")
    if any(x < 0 for row in w for x in row):
        raise ValueError("Weights must be nonnegative")
    return min((cut_weight(w, a), a) for a in subsets(n))
